using System;

static int Add(int a, int b) => a + b;

Console.WriteLine(Add(2, 3));

var numbers = new[] { 1, 2, 3, 4, 5 };
var doubled = numbers.Select(n => n * 2);
foreach (var n in doubled) Console.WriteLine(n);

public class Stack<T>
{
    private readonly List<T> _items = new();
    public void Push(T value) => _items.Add(value);
    public bool TryPop(out T value)
    {
        if (_items.Count == 0)
        {
            value = default!;
            return false;
        }
        value = _items[^1];
        _items.RemoveAt(_items.Count - 1);
        return true;
    }
}

public static IDictionary<TKey, List<T>> GroupBy<T, TKey>(
    IEnumerable<T> items,
    Func<T, TKey> keyFn) where TKey : notnull
{
    return items.GroupBy(keyFn).ToDictionary(g => g.Key, g => g.ToList());
}

public abstract record Result<T>
{
    public sealed record Ok(T Value) : Result<T>;
    public sealed record Err(string Message) : Result<T>;
}

public static async Task<T> RetryAsync<T>(Func<Task<T>> fn, int attempts = 3)
{
    Exception? last = null;
    for (var i = 0; i < attempts; i++)
    {
        try { return await fn(); }
        catch (Exception ex) { last = ex; }
    }
    throw last!;
}

public readonly record struct Page<T>(IReadOnlyList<T> Items, bool HasNext)
{
    public static Page<T> Empty => new(Array.Empty<T>(), false);
}
